require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../notices.php';oecrm_require_employee_login();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}oecrm_require_csrf();$employeeId=(int)$_SESSION['employeeId'];$noticeId=(int)($_POST['notice_id']??0);$action=$_POST['action']??'';$available=oecrm_employee_notices($conn,$employeeId,500);$notice=null;while($r=mysqli_fetch_assoc($available)){if((int)$r['id']===$noticeId){$notice=$r;break;}}if(!$notice){http_response_code(404);exit('Notice not available.');}if(!in_array($action,['read','acknowledge'],true)){http_response_code(400);exit('Invalid action.');}$ack=$action==='acknowledge';$ip=$_SERVER['REMOTE_ADDR']??'';$s=mysqli_prepare($conn,'INSERT INTO notice_receipts(notice_id,employee_id,first_seen_at,read_at,acknowledged_at,acknowledgement_ip) VALUES(?,?,NOW(),NOW(),IF(?=1,NOW(),NULL),IF(?=1,?,NULL)) ON DUPLICATE KEY UPDATE first_seen_at=COALESCE(first_seen_at,NOW()),read_at=COALESCE(read_at,NOW()),acknowledged_at=IF(?=1,COALESCE(acknowledged_at,NOW()),acknowledged_at),acknowledgement_ip=IF(?=1,?,acknowledgement_ip)');$one=$ack?1:0;mysqli_stmt_bind_param($s,'iiiisiis',$noticeId,$employeeId,$one,$one,$ip,$one,$one,$ip);mysqli_stmt_execute($s);mysqli_stmt_close($s);oecrm_notice_event($conn,$noticeId,$employeeId,'employee',$employeeId,$ack?'acknowledge':'read',$ack?'Employee acknowledged notice':'Employee marked notice read');$_SESSION['employee_notice_flash']=$ack?'Notice acknowledged.':'Notice marked as read.';header('Location: notices.php');exit;

